import {characteristicTitle} from './preflight.js?v=2.4.0';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function readinessBanner(report){return `<section class="readiness ${report.errors.length?'needs-input':'ready'}" aria-label="Analysis input checks"><div><strong>${report.errors.length?report.errors.length+' input '+(report.errors.length===1?'needs':'items need')+' attention':'No setup blockers found'}</strong><span>${report.warnings.length?report.warnings.length+' reference / data '+(report.warnings.length===1?'note':'notes')+' to review':'Checks update as you enter data'}</span></div><a href="#checks" class="ghost small">${report.errors.length?'Review & fix inputs':'View input checks'}</a></section>`;}
export function readinessList(report){const groups=new Map();for(const issue of report.issues){const key=[issue.device,issue.part,issue.category].filter(Boolean).join(' · ');let group=groups.get(key);if(!group){group=[];groups.set(key,group);}group.push(issue);}return `<p>Fix missing or invalid inputs before starting. Reference notes do not prevent a run. Temperature convergence and exact waveform-dependent curve queries are checked during calculation.</p><div class="check-counts"><strong>${report.errors.length} inputs to fix</strong><span>${report.warnings.length} notes to review</span></div>${groups.size?[...groups].map(([name,issues])=>`<section class="panel input-check-group"><h2>${esc(name)}</h2>${issues.map(issue=>`<div class="input-check ${issue.severity}"><div><span class="check-kind">${issue.severity==='error'?'Fix before analysis':'Review'}</span><p>${esc(issue.message)}</p>${issue.details?`<details><summary>More detail</summary><p class="caption">${esc(issue.details)}</p></details>`:''}</div><button class="ghost small" data-fix-issue="${esc(issue.id)}">Open & fix<span class="sr-only">: ${esc(issue.message)}</span></button><button type="button" class="ghost small" data-issue-help="${esc(issue.id)}">Help with this issue ?</button></div>`).join('')}</section>`).join(''):'<div class="notice">Your study passed the setup checks. You can run the analysis.</div>'}`;}
export function curveIssueHTML(issues){if(!issues.length)return '<p class="caption curve-valid">Curve points pass the data checks.</p>';return `<div class="curve-data-issues" role="status">${issues.map(issue=>`<div class="notice ${issue.severity==='error'?'error':'warn'}"><strong>${Number.isInteger(issue.iteration)?'Iteration '+(issue.iteration+1)+': ':''}</strong>${esc(issue.message)}</div>`).join('')}</div>`;}
